head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil50000";
scwin.form = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil50000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });
        await scwin.defaultCheck();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(clmschdlnotilist#getclmschdlnotilist vs clmschdlnotilist#editclmschdlnoti) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_clmSchdlNoti_oncellclick
 * @description grd_clmSchdlNoti 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_clmSchdlNoti */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { await scwin.openAdjReqPop(r["bzProcsNo"], "110"); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.editClmSchdlNoti(r["bzProcsNo"], "32", r["assgnYn"]); return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        await scwin.viewDetail(r["bzProcsNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_newWrite_onclick = function(e){
    try {
        scwin.newWrite()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil50000.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_75_onclick
 * @description krxpage_pagenavigator_75 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_75_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_75.page' }); } await scwin.fncSearch(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/clmSchdlNoti.do",
        ref: "dma_viewDetailReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/clmSchdlNotiList.do?method=getClmSchdlNotiList",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_editClmSchdlNoti
 * @description edit Clm Schdl Noti 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_editClmSchdlNoti = async function () {
    const sbmOptions = {
        id: "tx_editClmSchdlNoti",
        method: "post",
        action: "/listInvstg/clmSchdlNotiList.do?method=editClmSchdlNoti",
        ref: "dma_editClmSchdlNotiReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_clmSchdlNoti_fmt_column10
 * @description grd clm Schdl Noti fmt column10 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_fmt_column10 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_clmSchdlNoti");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "chCheck") ?? '') : '');
        if (['P','Y'].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_clmSchdlNoti.column10" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_clmSchdlNoti_fillAct
 * @description grd clm Schdl Noti fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo) {
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/listInvstg/clmSchdlNoti.do';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'editForm');
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil50100n/jldfil50100n.xml');
};

/**
 * @method
 * @name defaultCheck
 * @description default Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.defaultCheck = async function () {
    isOk = (String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (isOk !== '') {
        if ('true' === isOk) {
            await $c.win.alert('제출되었습니다');
        } else {
            await $c.win.alert('제출시 오류가 발생했습니다.');
        }
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil50000n/jldfil50000n.xml') + null;
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    scwin.form.action = "/listInvstg/clmSchdlNotiList.do?method=getClmSchdlNotiList";
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name editClmSchdlNoti
 * @description edit Clm Schdl Noti 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} status status
 * @param {String} assgnYn assgnYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.editClmSchdlNoti = async function (bzProcsNo, status, assgnYn) {
    scwin.form.action = "/listInvstg/clmSchdlNotiList.do?method=editClmSchdlNoti";
    $c.util.getComponent('dma_viewDetailReq').set('status', status);
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    if (assgnYn === 'Y') {
        if (await $c.win.confirm('제출하시겠습니까?')) {
            await scwin.tx_editClmSchdlNoti();
        }
    } else {
        await $c.win.alert('제출은 ID배정 이후에 가능합니다.');
    }
};

/**
 * @method
 * @name openAdjReqPop
 * @description open Adj Req Pop 처리
 * @param {*} prtdepoNo prtdepoNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPop = async function (prtdepoNo, listInvstgBzTpCd) {
    const data = { bzProcsNo: prtdepoNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: "23", callbackFn: "scwin.popupCallback" };
    const options = { id: "jldfil59411", popupName: "상장공시제출시스템 수정요청", width: 900, height: 380, frameModal: "top" };
    await $c.win.openPopup("/jldfil59411/jldfil59411.xml", options, data);
};
